+	if err := db.QueryRowContext(context.Background(), `SELECT COUNT(*) FROM notices WHERE task_id=? AND kind='greenhouse_review_failed'`, firstTask.ID).Scan(&failedNotices); err != nil || failedNotices != 0 {
