605: func recordGreenhouseVerdict(ctx context.Context, db *store.DB, task store.Task, member greenhouseMember, roundDir, blockAt string, cfg config.Config, result greenhouse.RoundResult) (bool, store.Verdict, error) {
606: 	hr := result.Result
607: 	findings, err := json.MarshalIndent(hr.Findings, "", "  ")
608: 	if err != nil {
609: 		return false, store.Verdict{}, err
610: 	}
611: 	path := filepath.Join(roundDir, strings.ReplaceAll(result.Grant, "/", "_")+".findings.json")
612: 	if err := atomicfile.Write(path, findings, 0o600); err != nil {
613: 		return false, store.Verdict{}, err
614: 	}
615: 	digest := sha256.Sum256(findings)
616: 	verdict := store.Verdict{
617: 		TaskID: task.ID, Repository: member.name, Provider: store.GreenhouseReviewProvider, Protocol: strconv.Itoa(greenhouse.Protocol),
618: 		Grant: result.Grant, Head: hr.Head, Target: hr.Target, ReviewBase: hr.ReviewBase, Outcome: hr.Verdict,
619: 		RulesDigest: hr.RulesDigest, ConfigDigest: hr.ConfigDigest, InputDigest: hr.InputDigest, Backend: hr.Backend, Model: hr.Model,
620: 		FindingsHash: hex.EncodeToString(digest[:]), FindingsPath: path, Mode: greenhouseVerdictMode(task, cfg, member.name),
621: 	}
622: 	for _, finding := range hr.Findings {
623: 		verdict.Findings = append(verdict.Findings, store.ProviderFinding{
624: 			Key: finding.ID, Severity: finding.Priority, Origin: finding.Origin, Path: finding.File, Line: finding.Start,
625: 			Excerpt: finding.Explanation, Guidance: finding.Action, Rule: finding.Rule, Head: finding.Head,
626: 		})
627: 	}
628: 	if hr.Verdict == "findings" {
629: 		verdict.Blocking = greenhouseBlocking(hr.Findings, blockAt)
630: 	}
631: 	recorded, err := db.RecordGreenhouseVerdict(ctx, verdict, func(ctx context.Context) (string, error) {
632: 		return gitOutput(ctx, member.worktree, "rev-parse", "HEAD")
633: 	})
634: 	return recorded, verdict, err
635: }
