292: 		case "quick", "local", "always":
293: 			local = true
294: 		case "full-pipeline":
295: 			fullPipeline = true
296: 		case store.GreenhouseReviewProvider:
297: 			greenhouse = true
298: 		case config.NoMistakes:
299: 			return noMistakesRemoved(task)
300: 		default:
