38: func providerPatternKey(finding ProviderFinding) string {
39: 	key := normalizeReviewPatternKey(finding.Rule)
40: 	if key == "" {
41: 		key = normalizeReviewPatternKey(finding.Origin)
42: 	}
43: 	if key == "" {
44: 		key = "unclassified"
45: 	}
46: 	return key
47: }
