85: func (db *DB) ProviderFindingsForTask(ctx context.Context, taskID int64) ([]ProviderFindingDetail, error) {
86: 	rows, err := db.QueryContext(ctx, `SELECT f.id,f.pattern_seq,p.key,p.title,p.rule,p.fix_guidance,f.repo,f.head_sha,f.path,f.line,f.excerpt,f.severity,f.origin,f.state
87: FROM provider_findings f JOIN provider_finding_patterns p ON p.task_id=f.task_id AND p.seq=f.pattern_seq
88: JOIN verdicts v ON v.id=f.verdict_id
89: WHERE f.task_id=? AND v.provider=f.provider AND v.id=(SELECT id FROM verdicts latest WHERE latest.task_id=f.task_id AND latest.repo=f.repo AND latest.provider=f.provider ORDER BY latest.recorded_at DESC,latest.id DESC LIMIT 1)
90: ORDER BY f.repo,f.pattern_seq,f.id`, taskID)
91: 	if err != nil {
92: 		return nil, err
93: 	}
94: 	defer rows.Close()
95: 	var findings []ProviderFindingDetail
96: 	for rows.Next() {
97: 		var finding ProviderFindingDetail
98: 		if err := rows.Scan(&finding.FindingSeq, &finding.PatternSeq, &finding.PatternKey, &finding.Title, &finding.Rule, &finding.FixGuidance,
99: 			&finding.Repository, &finding.HeadSHA, &finding.Path, &finding.Line, &finding.Excerpt, &finding.Severity, &finding.Origin, &finding.State); err != nil {
100: 			return nil, err
101: 		}
102: 		findings = append(findings, finding)
103: 	}
104: 	return findings, rows.Err()
105: }
