111: SELECT ?,f.id,f.pattern_seq FROM provider_findings f
112: WHERE f.task_id=? AND f.head_sha=? AND f.pattern_seq=? AND f.state IN ('open','disputed')
113: AND f.verdict_id=(SELECT id FROM verdicts v WHERE v.task_id=f.task_id AND v.repo=f.repo AND v.provider=f.provider ORDER BY v.recorded_at DESC,v.id DESC LIMIT 1)`, roundID, taskID, expectedHead, patternSeq); err != nil {
114: 				return err
115: 			}
116: 		} else {
