119: SELECT ?,f.id,f.pattern_seq FROM provider_findings f
120: WHERE f.task_id=? AND f.repo=? AND f.head_sha=? AND f.pattern_seq=? AND f.state IN ('open','disputed')
121: AND f.verdict_id=(SELECT id FROM verdicts v WHERE v.task_id=f.task_id AND v.repo=f.repo AND v.provider=f.provider ORDER BY v.recorded_at DESC,v.id DESC LIMIT 1)`, roundID, taskID, member.Repository, member.ExpectedBaseHead, patternSeq); err != nil {
122: 					return err
