137: func applyProviderFixAnswersTx(ctx context.Context, tx *writeTx, taskID int64, roundID int64, selected map[int]bool, answers map[int]ReviewFixResolution) error {
138: 	for patternSeq := range selected {
139: 		answer, found := answers[patternSeq]
140: 		if !found {
141: 			return fmt.Errorf("%w: missing answer for pattern P-%d", ErrReviewResolutionsRequired, patternSeq)
142: 		}
143: 		state, event := "fix_claimed", "fix_claimed"
144: 		if answer.Status == "disputed" {
145: 			state, event = "disputed", "disputed"
146: 		}
147: 		rows, err := tx.QueryContext(ctx, `SELECT f.id FROM provider_findings f JOIN fix_round_provider_findings r ON r.finding_id=f.id WHERE r.fix_round_id=? AND r.pattern_seq=? AND f.task_id=? AND f.state IN ('open','disputed')`, roundID, patternSeq, taskID)
148: 		if err != nil {
149: 			return err
150: 		}
151: 		var ids []int64
152: 		for rows.Next() {
153: 			var id int64
154: 			if err := rows.Scan(&id); err != nil {
155: 				rows.Close()
156: 				return err
157: 			}
158: 			ids = append(ids, id)
159: 		}
160: 		if err := rows.Err(); err != nil {
161: 			rows.Close()
162: 			return err
163: 		}
164: 		if err := rows.Close(); err != nil {
165: 			return err
166: 		}
167: 		if len(ids) == 0 {
168: 			return fmt.Errorf("%w: pattern P-%d has no open Greenhouse findings", ErrReviewResolutionsInvalid, patternSeq)
169: 		}
170: 		for _, id := range ids {
171: 			if _, err := tx.ExecContext(ctx, `UPDATE provider_findings SET state=? WHERE id=?`, state, id); err != nil {
