284: 	if err != nil {
285: 		return reviewFixHead{}, nil, err
286: 	}
287: 	checkouts := map[string]string{}
288: 	for _, repo := range repos {
289: 		checkouts[repo.Repo] = repo.WorktreePath
290: 	}
291: 	members := make([]reviewFixHead, 0, len(targets))
292: 	for _, target := range targets {
293: 		member := reviewFixHead{ValidationFixMemberHead: store.ValidationFixMemberHead{Repository: target.Repository, ExpectedBaseHead: target.Commit}, checkout: checkouts[target.Repository]}
