11: func taskUsesGreenhouseReviewProvider(task store.Task, cfg config.Config, repository string) bool {
12: 	plan, err := task.AdmittedPlan()
13: 	if err != nil || plan == nil {
14: 		return cfg.EffectiveReviewProvider(repository) == store.GreenhouseReviewProvider
15: 	}
16: 	if repository == "" && len(plan.Execution.Members) > 0 {
17: 		for _, member := range plan.Execution.Members {
18: 			provider := member.ReviewProvider
19: 			if provider == "" {
20: 				provider = plan.ReviewProvider
21: 			}
22: 			if provider == "" && plan.ValidationLoops != nil {
23: 				provider = plan.ValidationLoops.ReviewProvider
24: 			}
25: 			if provider == "" {
26: 				provider = cfg.EffectiveReviewProvider(member.Name)
27: 			}
28: 			if provider == store.GreenhouseReviewProvider {
29: 				return true
30: 			}
31: 		}
32: 		return false
33: 	}
34: 	if repository != "" {
35: 		for _, member := range plan.Execution.Members {
36: 			if member.Name == repository && member.ReviewProvider != "" {
37: 				return member.ReviewProvider == store.GreenhouseReviewProvider
38: 			}
39: 		}
40: 	}
41: 	if plan.ReviewProvider != "" {
42: 		return plan.ReviewProvider == store.GreenhouseReviewProvider
43: 	}
44: 	if plan.ValidationLoops != nil && plan.ValidationLoops.ReviewProvider != "" {
45: 		return plan.ValidationLoops.ReviewProvider == store.GreenhouseReviewProvider
46: 	}
