35: 			return db.RecordWorkerSignalWithValidation(ctx, task, verb, note, data, noticeKind, *validation)
36: 		}
37: 		if reviewResolutions != nil {
38: 			return db.RecordWorkerSignalWithResolutions(ctx, task, verb, note, data, noticeKind, verdict, reviewResolutions)
39: 		}
40: 		return db.RecordWorkerSignalWithVerdict(ctx, task, verb, note, data, noticeKind, verdict)
41: 	}
42: 	if verb != "done" || task.Type != "change" || inPlace || project.IsWorkspace() || greenhouseFullPipelineTaskWithConfig(task, cfg, "") {
43: 		return record(nil)
44: 	}
45: 	for attempt := 0; attempt < 3; attempt++ {
46: 		validation, err := s.checkedValidationContinuity(ctx, db, project, task)
