121: 	if err != nil {
122: 		return 0, err
123: 	}
124: 	defer rows.Close()
125: 	blocking := 0
126: 	for rows.Next() {
127: 		var severity string
128: 		if err := rows.Scan(&severity); err != nil {
129: 			return 0, err
130: 		}
131: 		rank, known := map[string]int{"P0": 0, "P1": 1, "P2": 2, "P3": 3}[severity]
132: 		if !known || rank <= threshold {
133: 			blocking++
134: 		}
135: 	}
136: 	return blocking, rows.Err()
