637: // greenhouseBlocking counts findings at or above blockAt. An unknown priority blocks.
638: func greenhouseBlocking(findings []greenhouse.Finding, blockAt string) int {
639: 	rank := map[string]int{"P0": 0, "P1": 1, "P2": 2, "P3": 3}
640: 	threshold := rank[blockAt]
641: 	blocking := 0
642: 	for _, finding := range findings {
643: 		if priority, known := rank[finding.Priority]; !known || priority <= threshold {
644: 			blocking++
645: 		}
646: 	}
647: 	return blocking
648: }
