262: // reviewFixHeads returns the single-repository head, or one head per changed
263: // workspace Member. A full-pipeline lane binds its active private candidate.
264: func reviewFixHeads(ctx context.Context, db *store.DB, project store.Project, change store.Task, greenhouse bool) (reviewFixHead, []reviewFixHead, error) {
265: 	targets, err := changeCandidateTargets(ctx, db, project, change)
266: 	if err != nil {
267: 		return reviewFixHead{}, nil, err
268: 	}
269: 	if !project.IsWorkspace() {
270: 		if len(targets) != 1 {
271: 			return reviewFixHead{}, nil, axi.Failure("review_fix_unsupported", "Review fix requires one repository head", false)
272: 		}
273: 		head := reviewFixHead{ValidationFixMemberHead: store.ValidationFixMemberHead{ExpectedBaseHead: targets[0].Commit}}
274: 		if fullPipelineSelected(change, "") && !greenhouse {
275: 			candidate, err := activeReviewFixCandidate(ctx, db, change, "")
276: 			if err != nil {
277: 				return reviewFixHead{}, nil, err
278: 			}
279: 			head.ExpectedBaseHead, head.CandidateID, head.checkout = candidate.CandidateSHA, candidate.ID, candidate.WorktreePath
280: 		}
281: 		return head, nil, nil
282: 	}
283: 	repos, err := db.TaskRepos(ctx, change.ID)
284: 	if err != nil {
285: 		return reviewFixHead{}, nil, err
286: 	}
287: 	checkouts := map[string]string{}
288: 	for _, repo := range repos {
289: 		checkouts[repo.Repo] = repo.WorktreePath
290: 	}
291: 	members := make([]reviewFixHead, 0, len(targets))
292: 	for _, target := range targets {
293: 		member := reviewFixHead{ValidationFixMemberHead: store.ValidationFixMemberHead{Repository: target.Repository, ExpectedBaseHead: target.Commit}, checkout: checkouts[target.Repository]}
294: 		if fullPipelineSelected(change, target.Repository) && !greenhouse {
295: 			candidate, err := activeReviewFixCandidate(ctx, db, change, target.Repository)
296: 			if err != nil {
297: 				return reviewFixHead{}, nil, err
298: 			}
299: 			member.ExpectedBaseHead, member.CandidateID, member.checkout = candidate.CandidateSHA, candidate.ID, candidate.WorktreePath
300: 		}
301: 		members = append(members, member)
302: 	}
303: 	return reviewFixHead{}, members, nil
304: }
