472: 				break
473: 			}
474: 			if !latest.Qualifies(target.Commit) {
475: 				allPassed = false
476: 				failed = latest
477: 				break
478: 			}
479: 		}
480: 		if !allPassed {
481: 			if failed != nil && failed.Outcome == "findings" && failed.Blocking > 0 {
