144: 		}
145: 		changed++
146: 		if !fullPipelineSelected(task, repo.Repo) || !taskUsesGreenhouseReviewProvider(task, cfg, repo.Repo) {
147: 			return false, nil
148: 		}
149: 	}
150: 	return changed > 0, nil
