75: func TestGreenhouseFullPipelinePrepublicationReviewRunsFromWatch(t *testing.T) {
76: 	f := newWorkerTabsFixture(t)
77: 	c := newGreenhouseContract(t, f)
78: 	c.env = setEnv(c.env, "GREENHOUSE_HOME", c.home)
79: 	t.Cleanup(func() {
80: 		find := func() ([]isolatedHerdrServerProcess, error) {
81: 			processes, err := findSpawnedProcesses(func(_ []byte, cwd string) bool { return strings.HasPrefix(cwd, f.root) })
82: 			var daemons []isolatedHerdrServerProcess
83: 			for _, process := range processes {
84: 				if strings.Contains(process.Args, "/bin/greenhouse daemon") {
85: 					daemons = append(daemons, process)
86: 				}
87: 			}
88: 			return daemons, err
89: 		}
90: 		for attempt := 0; attempt < 4; attempt++ {
91: 			if err := stopProcesses("Greenhouse daemon", find, 3*time.Second); err != nil {
92: 				t.Errorf("stop fixture Greenhouse daemon: %v", err)
93: 				return
94: 			}
95: 			time.Sleep(250 * time.Millisecond)
96: 			processes, err := find()
97: 			if err != nil || len(processes) == 0 {
98: 				return
99: 			}
100: 		}
101: 		t.Errorf("Greenhouse daemon restarted during cleanup")
102: 	})
103: 	projectDB, err := store.OpenReadOnly(f.home)
104: 	if err != nil {
105: 		t.Fatal(err)
106: 	}
107: 	project, err := projectDB.ProjectByID(context.Background(), f.projectID)
108: 	projectDB.Close()
109: 	if err != nil {
110: 		t.Fatal(err)
111: 	}
112: 	projectDir := filepath.Join(f.home, "projects", project.Name)
113: 	if err := os.WriteFile(filepath.Join(projectDir, "config.toml"), []byte("review_provider = \"greenhouse\"\n[defaults]\nreview = \"full-pipeline\"\nmerge_mode = \"local\"\n"), 0o600); err != nil {
114: 		t.Fatal(err)
115: 	}
116: 	c.change = f.start(t, "t1", "Greenhouse prepublication change", "greenhouse-prepubl")
117: 	head := c.authorCommit(t)
118: 	workerEnv := setEnv(c.env, "POSSE_TASK_ID", c.change.ContainmentMarker)
119: 	workerEnv = setEnv(workerEnv, "HERDR_PANE_ID", c.change.PaneID)
120: 	if output, err := c.posse(workerEnv, c.change.WorktreePath, "signal", "done", "Greenhouse prepublication change", "--head", head); err != nil {
121: 		t.Fatalf("Worker done Signal: %v\n%s", err, output)
122: 	}
123: 	if task := f.task(t, "t1"); task.State != store.StateDone || task.PRURL != "" {
124: 		t.Fatalf("prepublication Task state = %#v", task)
125: 	}
126: 	if output, err := c.posse(c.env, f.repo, "watch", "--poll-only", "--timeout", "3000"); err != nil {
127: 		t.Fatalf("Lead Watch: %v\n%s", err, output)
128: 	}
129: 	if !waitForCondition(60*time.Second, func() bool { return len(c.verdicts(t)) > 0 }) {
130: 		t.Fatal("Watch did not request a Greenhouse Verdict")
131: 	}
132: 	if output, err := c.posse(c.env, f.repo, "watch", "--poll-only", "--timeout", "3000"); err != nil {
133: 		t.Fatalf("Lead Watch follow-up pass: %v\n%s", err, output)
134: 	}
135: 	verdicts := c.verdicts(t)
136: 	verdict := verdicts[len(verdicts)-1]
137: 	if verdict.Mode != "gate" || verdict.Head != head || !verdict.Qualifies(head) {
138: 		t.Fatalf("Watch Verdict = %+v, want passing gate for %s", verdict, head)
139: 	}
140: 	if _, err := os.Stat(filepath.Join(projectDir, "tasks", "t1", "candidate")); err == nil {
141: 		t.Fatal("Greenhouse full-pipeline created a private candidate")
142: 	}
143: 	db, err := store.OpenReadOnly(f.home)
144: 	if err != nil {
145: 		t.Fatal(err)
146: 	}
147: 	var reviews int
148: 	err = db.QueryRowContext(context.Background(), `SELECT COUNT(*) FROM tasks WHERE reviews_task_id=?`, c.change.ID).Scan(&reviews)
149: 	var handoffs int
150: 	if err == nil && reviews == 0 {
151: 		err = db.QueryRowContext(context.Background(), `SELECT COUNT(*) FROM messages WHERE task_id=? AND body LIKE '%Publish this exact head%'`, c.change.ID).Scan(&handoffs)
152: 	}
153: 	_ = db.Close()
154: 	if err != nil || reviews != 0 || handoffs != 1 {
155: 		t.Fatalf("Review Tasks = %d, publication handoffs = %d (want 1): %v", reviews, handoffs, err)
156: 	}
157: 	if output, err := c.posse(c.env, f.repo, "merge", "t1", "--execute", "--user-approved", "User approved the Greenhouse-reviewed change"); err != nil {
158: 		t.Fatalf("Lead merge: %v\n%s", err, output)
159: 	}
160: 	merged := f.task(t, "t1")
161: 	if merged.State != store.StateMerged || merged.MergedRef != head || merged.GatedSHA != head {
162: 		t.Fatalf("merged head is not the passing Greenhouse head %s: %#v", head, merged)
163: 	}
164: }
