30: func providerFindingKey(finding ProviderFinding) string {
31: 	if key := strings.TrimSpace(finding.Key); key != "" {
32: 		return key
33: 	}
34: 	sum := sha256.Sum256([]byte(strings.Join([]string{finding.Rule, finding.Path, fmt.Sprint(finding.Line), finding.Excerpt}, "\x00")))
35: 	return hex.EncodeToString(sum[:])
36: }
