49: func recordProviderFindingsTx(ctx context.Context, tx *sql.Tx, verdictID int64, verdict Verdict) error {
50: 	for _, finding := range verdict.Findings {
51: 		if finding.Head != "" && finding.Head != verdict.Head {
52: 			return fmt.Errorf("provider finding %q is bound to head %s, not Verdict head %s", finding.Key, finding.Head, verdict.Head)
53: 		}
54: 		if strings.TrimSpace(finding.Path) == "" || finding.Line < 1 {
55: 			return fmt.Errorf("provider finding %q has no path or positive line", finding.Key)
56: 		}
57: 		key := providerPatternKey(finding)
58: 		var patternSeq int
59: 		err := tx.QueryRowContext(ctx, `SELECT seq FROM provider_finding_patterns WHERE task_id=? AND key=?`, verdict.TaskID, key).Scan(&patternSeq)
60: 		if err == sql.ErrNoRows {
61: 			if err := tx.QueryRowContext(ctx, `SELECT COALESCE(MAX(seq),0)+1 FROM provider_finding_patterns WHERE task_id=?`, verdict.TaskID).Scan(&patternSeq); err != nil {
62: 				return err
63: 			}
64: 			title := strings.TrimSpace(finding.Rule)
65: 			if title == "" {
66: 				title = strings.TrimSpace(finding.Guidance)
67: 			}
68: 			if title == "" {
69: 				title = "Provider finding pattern"
70: 			}
71: 			if _, err := tx.ExecContext(ctx, `INSERT INTO provider_finding_patterns(task_id,seq,key,title,rule,fix_guidance) VALUES(?,?,?,?,?,?)`, verdict.TaskID, patternSeq, key, title, finding.Rule, finding.Guidance); err != nil {
72: 				return err
73: 			}
74: 		} else if err != nil {
75: 			return err
76: 		}
77: 		if _, err := tx.ExecContext(ctx, `INSERT INTO provider_findings(verdict_id,task_id,provider,repo,head_sha,finding_key,pattern_seq,path,line,excerpt,severity,origin,state) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,'open')`,
78: 			verdictID, verdict.TaskID, verdict.Provider, verdict.Repository, verdict.Head, providerFindingKey(finding), patternSeq, finding.Path, finding.Line, finding.Excerpt, finding.Severity, finding.Origin); err != nil {
79: 			return err
80: 		}
81: 	}
82: 	return nil
83: }
