280: // requireSelectedReviewForMerge is the one evidence check before and after a
281: // forge merge. After it, mergeCommit names the merge, and full-pipeline
282: // evidence is checked against the target tip that merge landed on.
283: func requireSelectedReviewForMerge(ctx context.Context, db *store.DB, project store.Project, cfg config.Config, task store.Task, commit, mergeCommit string) error {
284: 	policies, err := selectedReviewPolicies(ctx, db, project, cfg, task)
285: 	if err != nil {
286: 		return err
287: 	}
288: 	local, fullPipeline, greenhouse := false, false, false
289: 	for _, selected := range policies {
290: 		switch selected {
291: 		case "none":
292: 		case "quick", "local", "always":
293: 			local = true
294: 		case "full-pipeline":
295: 			fullPipeline = true
296: 		case store.GreenhouseReviewProvider:
297: 			greenhouse = true
298: 		case config.NoMistakes:
299: 			return noMistakesRemoved(task)
300: 		default:
301: 			return axi.Failure("review_policy_invalid", "unsupported selected review policy "+selected, false)
302: 		}
303: 	}
304: 	// A mixed workspace needs both: full-pipeline Members their barrier and
305: 	// quick Members their own exact-head review.
306: 	if fullPipeline {
307: 		if err := requireFullPipelineValidationAt(ctx, db, project, cfg, task, commit, mergeCommit); err != nil {
308: 			return err
309: 		}
310: 	}
311: 	if local {
312: 		if err := requireReviewPass(ctx, db, project, task, commit); err != nil {
313: 			return err
314: 		}
315: 	}
316: 	if greenhouse {
317: 		if err := requireGreenhouseGatePass(ctx, db, project, cfg, task, commit, ""); err != nil {
318: 			return err
319: 		}
320: 	}
321: 	return requireNoBlockingReviewFinding(ctx, db, task)
322: }
