343: // selectedReviewPolicies lists the admitted policy of the Task, or of each
344: // changed workspace Member. A version-1 plan keeps its frozen legacy value:
345: // only `always` required a pass, so the other legacy values select none.
346: func selectedReviewPolicies(ctx context.Context, db *store.DB, project store.Project, cfg config.Config, task store.Task) ([]string, error) {
347: 	plan, err := task.AdmittedPlan()
348: 	if err != nil {
349: 		return nil, admittedPlanFailure(err)
350: 	}
351: 	policy := cfg.Defaults.Review
352: 	if plan != nil {
353: 		if taskUsesGreenhouseReviewProvider(task, cfg, "") {
354: 			if !project.IsWorkspace() {
355: 				return []string{store.GreenhouseReviewProvider}, nil
356: 			}
357: 			policy = store.GreenhouseReviewProvider
358: 		} else {
359: 			policy = plan.Review
360: 		}
361: 		if plan.Version == 1 {
362: 			if policy == "always" {
363: 				return []string{"always"}, nil
364: 			}
365: 			return nil, nil // Frozen legacy behavior, not an inferred evidence guarantee.
366: 		}
367: 	}
368: 	if !project.IsWorkspace() {
369: 		return []string{policy}, nil
370: 	}
371: 	repos, err := db.TaskRepos(ctx, task.ID)
372: 	if err != nil {
373: 		return nil, err
374: 	}
375: 	var policies []string
376: 	for _, repo := range repos {
377: 		if repo.State == store.TaskRepoMerged {
378: 			continue
379: 		}
380: 		ahead, err := commitsAhead(ctx, repo.WorktreePath, repo.BaseRef, "refs/heads/"+task.Branch)
381: 		if err != nil {
382: 			return nil, memberFailure(repo.Repo, err)
383: 		}
384: 		if ahead == 0 {
385: 			continue
386: 		}
387: 		selected := cfg.MemberReview(repo.Repo)
388: 		if taskUsesGreenhouseReviewProvider(task, cfg, repo.Repo) {
389: 			selected = store.GreenhouseReviewProvider
390: 		}
391: 		if plan != nil && selected != store.GreenhouseReviewProvider {
392: 			selected = ""
393: 			for _, member := range plan.Execution.Members {
394: 				if member.Name == repo.Repo {
395: 					selected = member.Review
396: 					break
397: 				}
398: 			}
399: 		}
400: 		policies = append(policies, selected)
401: 	}
402: 	return policies, nil
