13: func (s *Service) recordWorkerSignalWithContinuity(
14: 	ctx context.Context,
15: 	db *store.DB,
16: 	project store.Project,
17: 	cfg config.Config,
18: 	task store.Task,
19: 	verb, note string,
20: 	data any,
21: 	noticeKind string,
22: 	verdict *store.ReviewVerdictInput,
23: 	inPlace bool,
24: 	resolutions ...*store.ReviewFixResolutionsInput,
25: ) (store.State, error) {
26: 	var reviewResolutions *store.ReviewFixResolutionsInput
27: 	if len(resolutions) > 0 {
28: 		reviewResolutions = resolutions[0]
29: 	}
30: 	record := func(validation *store.ValidationContinuitySnapshot) (store.State, error) {
31: 		if validation != nil {
32: 			if reviewResolutions != nil {
33: 				return db.RecordWorkerSignalWithValidationAndResolutions(ctx, task, verb, note, data, noticeKind, *validation, reviewResolutions)
34: 			}
35: 			return db.RecordWorkerSignalWithValidation(ctx, task, verb, note, data, noticeKind, *validation)
36: 		}
37: 		if reviewResolutions != nil {
38: 			return db.RecordWorkerSignalWithResolutions(ctx, task, verb, note, data, noticeKind, verdict, reviewResolutions)
39: 		}
40: 		return db.RecordWorkerSignalWithVerdict(ctx, task, verb, note, data, noticeKind, verdict)
41: 	}
42: 	if verb != "done" || task.Type != "change" || inPlace || project.IsWorkspace() || greenhouseFullPipelineTaskWithConfig(task, cfg, "") {
43: 		return record(nil)
44: 	}
45: 	for attempt := 0; attempt < 3; attempt++ {
46: 		validation, err := s.checkedValidationContinuity(ctx, db, project, task)
47: 		if err != nil {
48: 			return "", err
49: 		}
50: 		state, err := record(&validation)
51: 		if !errors.Is(err, store.ErrValidationHeadsChanged) {
52: 			return state, err
53: 		}
54: 	}
55: 	return "", axi.Failure(
56: 		"head_discontinuity",
57: 		"automatic validation instructions changed repeatedly while recording the done Signal",
58: 		true,
59: 		"Retry `posse signal done` after the validation instructions settle",
60: 	)
61: }
